"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Evidence-reliability experiment, step 2, version 2 of the reliability read-out (dev; approved by the author
2026-11-23). Version 1 (scripts/p1v4_reliability_fix.py, results/main_v04/reliability_step2_dev.json) passed only
criterion 4: it swung from trusting the ears to leaning on the labels, one fixed compromise.

The one change from version 1: a clarity signal read from the model's own audio encoder, and read-out weights that
depend on it. Everything else as version 1: the same mixed train set (data/p1v4/runs/reliability/fix/), holdout units,
weight-decay grid, optimiser, operating-point rule on natural dev, step-1 dev grid and the plan's four criteria.
  clarity probe: ridge regression from the whole-window ears (mean and max over the 104 encoder tokens, 2,048,
    computed from the per-second ears) to the window's signal-to-noise ratio in dB (the unit's spec snr_db minus the
    added dB), fitted on the R-hear and S-move train windows (clean and noisy); alpha by holdout mean absolute error
    on the same holdout units as the read-out fits; clarity c = clip((predicted SNR + 20) / 50, 0, 1).
  read-out: per question a logistic regression on [x, c * x, c], x = the main system's inputs (states at the option
    positions + per-second ears), so every weight is w + c * w' and the intercept moves with c.
The plan's fallback said the clarity signal would be computed from the waveform; on the author's choice it is read from
the encoder instead (model-internal).
Commands (repo root, .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_reliability_fix2.py ...):
  probe   fit the clarity probe; its holdout error; predicted SNR on the dev grid by level
  fit     the version-2 read-out; its operating point on natural dev
  eval    dev: the step-1 grid and the four criteria for the main system, version 1 and version 2
          -> results/main_v04/reliability_step2v2_dev.json
"""
import collections
import json
import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_reliability_fix as FIX  # noqa: E402

OUT = FIX.FIX
ALPHAS = (1.0, 10.0, 100.0, 1000.0, 10000.0)
SNR_LO, SNR_HI = -20.0, 30.0


def whole(sm, sx):
    """Whole-window ears (mean and max over the 104 tokens) from the per-second mean and max (13 tokens a second)."""
    return np.concatenate([np.asarray(sm, np.float32).mean(1), np.asarray(sx, np.float32).max(1)], 1)


def clarity_of(W, pr):
    snr = ((W - pr["mu"]) / pr["sd"]) @ pr["w"] + float(pr["b"])
    return np.clip((snr - SNR_LO) / (SNR_HI - SNR_LO), 0.0, 1.0), snr


def holdout_units():
    import p1v4_readout as RO
    z = np.load(FIX.F2C)
    rng = np.random.default_rng(RO.SEED)                    # the same holdout units as the read-out fits
    uniq = np.unique(z["units"])
    return set(rng.choice(uniq, size=len(uniq) // 5, replace=False))


# ------------------------------------------------------------------------------------------------ probe

def probe():
    a = FIX.load_assign()
    rows, wins = FIX.train_rows()
    snr0 = {r["unit"]: float(r["spec"]["snr_db"]) for r in rows if r["part"] in FIX.NOISY_PARTS}
    e = np.load(FIX.FSEC)
    ids = [str(i) for i in e["ids"]]
    pos = {i: n for n, i in enumerate(ids)}
    zz = np.load(os.path.join(OUT, "feats_train_noisy.npz"))
    noisy = {str(i): n for n, i in enumerate(zz["ids"])}
    keep = [w for w in wins if w["unit"] in snr0]
    clean_rows = [pos[w["id"]] for w in keep if w["id"] not in noisy]
    noisy_rows = [noisy[w["id"]] for w in keep if w["id"] in noisy]
    Wc = whole(e["sec_mean"][clean_rows], e["sec_max"][clean_rows])
    Wn = whole(zz["sec_mean"][noisy_rows], zz["sec_max"][noisy_rows])
    W = np.concatenate([Wc, Wn])
    kc = [w for w in keep if w["id"] not in noisy]
    kn = [w for w in keep if w["id"] in noisy]
    y = np.array([snr0[w["unit"]] for w in kc] + [snr0[w["unit"]] - a["unit_db"][w["unit"]] for w in kn], np.float64)
    units = np.array([w["unit"] for w in kc] + [w["unit"] for w in kn])
    hu = holdout_units()
    hold = np.array([u in hu for u in units])
    mu, sd = W[~hold].mean(0), W[~hold].std(0) + 1e-6
    X = (W - mu) / sd
    log, best = {}, None
    for alpha in ALPHAS:
        A = X[~hold].T @ X[~hold] + alpha * np.eye(X.shape[1])
        ym = y[~hold].mean()
        w = np.linalg.solve(A, X[~hold].T @ (y[~hold] - ym))
        mae = float(np.mean(np.abs(X[hold] @ w + ym - y[hold])))
        log[f"alpha {alpha}"] = mae
        print(f"clarity probe alpha {alpha}: holdout MAE {mae:.2f} dB", flush=True)
        if best is None or mae < best[0]:
            best = (mae, alpha)
    mu, sd = W.mean(0), W.std(0) + 1e-6
    X = (W - mu) / sd
    ym = y.mean()
    w = np.linalg.solve(X.T @ X + best[1] * np.eye(X.shape[1]), X.T @ (y - ym))
    pr = {"mu": mu.astype(np.float32), "sd": sd.astype(np.float32), "w": w.astype(np.float32), "b": ym}
    np.savez(os.path.join(OUT, "clarity_probe.npz"), **pr, alpha=best[1])
    yh = X @ w + ym
    res = {"alpha": best[1], "holdout_mae_db": best[0], "grid": log, "train_windows": len(y),
           "train_r2": float(1 - np.var(y - yh) / np.var(y)), "dev_by_level": {}}
    # dev grid: predicted SNR by level (true SNR = spec snr_db minus the level's dB)
    import p1v4_grounding as G
    rows_dev, _ = G.load("dev")
    snr_dev = {r["unit"]: float(r["spec"]["snr_db"]) for r in rows_dev}
    for lv in ("dclean", "dnoise10", "dnoise20", "dnoise30", "dnoise40"):
        z = np.load(f"{FIX.REL_DEV}/{lv}/l1_none.npz")
        c, snr = clarity_of(whole(z["sec_mean"], z["sec_max"]), pr)
        db = 0 if lv == "dclean" else int(lv[6:])
        true = np.array([snr_dev[str(u)] - db for u in z["units"]])
        res["dev_by_level"][lv] = {"true_snr_mean": float(true.mean()), "pred_snr_mean": float(snr.mean()),
                                   "mae_db": float(np.mean(np.abs(snr - true))), "clarity_mean": float(c.mean())}
    json.dump(res, open(os.path.join(OUT, "clarity_probe.json"), "w"), indent=1)
    print(json.dumps({k: v for k, v in res.items() if k != "grid"}, indent=1), flush=True)


def load_probe():
    z = np.load(os.path.join(OUT, "clarity_probe.npz"))
    return {k: z[k] for k in ("mu", "sd", "w", "b")}


# ------------------------------------------------------------------------------------------------ read-out v2

def design2(states, sm, sx, c):
    import p1v4_readout_2d as R2D
    X = R2D.design(states, sm, sx)
    return np.concatenate([X, c[:, None] * X, c[:, None]], 1).astype(np.float32)


def scores_v2(z, sec, ro, pr):
    """{(unit, version, k): {"S": p, "R": p}}; z holds states, q_win, q_task, ids; sec = p1v4_readout_2d.Sec."""
    wid = z["ids"][z["q_win"]]
    p = np.zeros(len(z["q_task"]))
    for q in ("S", "R"):
        m = np.where(z["q_task"] == q)[0]
        if not len(m):
            continue
        r = sec.rows(wid[m])
        sm, sx = sec.sm[r], sec.sx[r]
        c, _ = clarity_of(whole(sm, sx), pr)
        X = design2(z["states"][m], sm, sx, c)
        lg = ((X - ro[q]["mu"]) / ro[q]["sd"]) @ ro[q]["w"] + float(ro[q]["b"])
        p[m] = 1 / (1 + np.exp(-lg))
    sc = {}
    for w, q, x in zip(z["q_win"], z["q_task"], p):
        i = z["ids"][w].split("|")
        sc.setdefault((i[0], i[1], int(i[2])), {})[str(q)] = float(x)
    return sc


def fit():
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    import p1v4_score as S
    D.gpu_guard()
    pr = load_probe()
    z, states, sm_all, sx_all, counts = FIX.mixed_train()
    c_win, _ = clarity_of(whole(sm_all, sx_all), pr)
    units = z["units"][z["q_win"]]
    hu = holdout_units()
    hold = np.array([u in hu for u in units])
    log, models = {"counts": counts, "clarity_train_mean": float(c_win.mean())}, {}
    for q in ("S", "R"):
        m = np.where((z["q_task"] == q) & (z["q_gold"] >= 0))[0]
        wq = z["q_win"][m]
        X = design2(states[m], sm_all[wq], sx_all[wq], c_win[wq])
        mu, sd = X.mean(0), X.std(0) + 1e-6
        X -= mu
        X /= sd
        Xh = X.astype(np.float16)
        del X
        y = z["q_gold"][m]
        hm = hold[m]
        best = None
        for wd in RO.WDS:
            lin = RO.train_logreg(Xh[~hm], y[~hm], wd)
            p = np.clip(RO.predict(lin, Xh[hm]), 1e-7, 1 - 1e-7)
            yy = y[hm]
            ll = float(-np.mean(yy * np.log(p) + (1 - yy) * np.log(1 - p)))
            log[f"rel2 {q} wd {wd}"] = ll
            print(f"reliability v2 {q} wd {wd}: holdout log loss {ll:.4f}", flush=True)
            if best is None or ll < best[0]:
                best = (ll, wd)
            del lin
        lin = RO.train_logreg(Xh, y, best[1])
        models[q] = {"mu": mu, "sd": sd, "w": lin.weight.detach().cpu().numpy()[0],
                     "b": float(lin.bias.detach().cpu().numpy()[0]), "wd": best[1]}
        del Xh, lin
    np.savez(os.path.join(OUT, "readouts_rel2.npz"),
             **{f"rel2|{q}|{f}": v for q, d in models.items() for f, v in d.items()})
    rows = D.load_rows("dev")
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    sc = scores_v2(zn, R2D.Sec(), load_rel2(), pr)
    op = S.operating_point(rows, sc)
    log["operating_point"] = {k: op[k] for k in ("th_s", "th_r", "floors_met", "primary", "lowest_floor")}
    json.dump(log, open(os.path.join(OUT, "fit2_log.json"), "w"), indent=1, default=float)
    print("fitted:", {q: d["wd"] for q, d in models.items()}, "operating point:", log["operating_point"], flush=True)


def load_rel2():
    z = np.load(os.path.join(OUT, "readouts_rel2.npz"))
    out = {}
    for k in z.files:
        _, q, f = k.split("|")
        out.setdefault(q, {})[f] = z[k]
    return out


# ------------------------------------------------------------------------------------------------ eval

def eval_():
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    import p1v4_reliability_dev as RD
    import p1v4_score as S
    import p1v4_step0_confidence as S0
    st = RD.rehearsal_settings()
    op1 = json.load(open(os.path.join(OUT, "fit_log.json")))["operating_point"]
    op2 = json.load(open(os.path.join(OUT, "fit2_log.json")))["operating_point"]
    th = {"2d": (st["main"]["th_s"], st["main"]["th_r"]),
          "old head": (st["local"]["L1"]["th_s"], st["local"]["L1"]["th_r"]),
          "rel v1": (op1["th_s"], op1["th_r"]), "rel v2": (op2["th_s"], op2["th_r"])}
    ro2d, ro1, ro2, pr = R2D.load_2d(), FIX.load_rel(), load_rel2(), load_probe()

    def scores(z):
        sec = R2D.Sec(None, z["ids"], z["sec_mean"], z["sec_max"])
        return {"2d": RD.keyed(R2D.scores_2d(z, sec, ro2d)), "old head": RD.keyed(RO.scores_of(z, None, None)),
                "rel v1": RD.keyed(R2D.scores_2d(z, sec, ro1)), "rel v2": RD.keyed(scores_v2(z, sec, ro2, pr))}
    res = {"split": "dev", "note": "exploratory (evidence-reliability step 2, version 2: clarity-dependent weights)",
           "thresholds": th, "clarity_probe": json.load(open(os.path.join(OUT, "clarity_probe.json"))),
           "cells": {}, "groups_all_right": {}, "natural": {}, "criteria": {}}
    for lv in RD.LEVELS:
        for cond in RD.CONDS:
            z = dict(np.load(f"{FIX.REL_DEV}/{lv}/l1_{cond}.npz"))
            sc = scores(z)
            for n in th:
                qs = RD.questions(z, sc[n], th[n])
                for part in ("r_hear", "s_move"):
                    sel = [x for x in qs if x[1] == part]
                    if not sel:
                        continue
                    res["cells"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {})[lv] = \
                        S0.summary([x[4] for x in sel], [x[5] for x in sel])
                    ok = collections.defaultdict(lambda: True)
                    for x in sel:
                        ok[x[0]] = ok[x[0]] and bool(x[5])
                    res["groups_all_right"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {})[lv] = \
                        float(np.mean(list(ok.values())))
    rows = D.load_rows("dev")
    gmap = S.load_groups("dev")
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    sec = R2D.Sec()
    nat_sc = {"2d": R2D.scores_2d(zn, sec, ro2d), "rel v1": R2D.scores_2d(zn, sec, ro1),
              "rel v2": scores_v2(zn, sec, ro2, pr)}
    for n, sc in nat_sc.items():
        m = S.metrics(S.unit_table(rows, S.decide(sc, *th[n]), gmap))
        res["natural"][n] = {"primary": m["primary"], "parts": m["parts"], "floors": m["floors"]}
    C_, G_ = res["cells"], res["groups_all_right"]
    for n in ("rel v1", "rel v2"):
        crit = {}
        c1 = {}
        for part in ("r_hear", "s_move"):
            for lv in ("dnoise20", "dnoise30", "dnoise40"):
                new, old = C_[part]["truth"][n][lv]["accuracy"], C_[part]["truth"]["old head"][lv]["accuracy"]
                c1[f"{part} {lv}"] = {"value": new, "old head": old, "gap": new - old, "pass": new >= old - 0.05}
        crit["1 truth labels, bad ears"] = {"cells": c1, "pass": all(v["pass"] for v in c1.values())}
        c2 = {}
        for part in ("r_hear", "s_move"):
            for lv in ("dnoise30", "dnoise40"):
                x = C_[part]["none"][n][lv]
                ce, cs = x["confident_error_rate"], x["confident_share"]
                c2[f"{part} {lv}"] = {"confident_error_rate": ce, "confident_share": cs,
                                      "main system": C_[part]["none"]["2d"][lv]["confident_error_rate"],
                                      "pass": ce is not None and ce <= 0.10 and cs >= 0.25}
        crit["2 no labels, bad ears"] = {"cells": c2, "pass": all(v["pass"] for v in c2.values())}
        c3 = {}
        for part, cond in (("r_hear", "c0.99"), ("s_move", "mv0.99")):
            new, main = G_[part][cond][n]["dclean"], G_[part][cond]["2d"]["dclean"]
            c3[part] = {"value": new, "main system": main, "gap": new - main, "pass": new >= main - 0.05}
        crit["3 fake labels, clean ears"] = {"cells": c3, "pass": all(v["pass"] for v in c3.values())}
        nn, nm = res["natural"][n]["primary"], res["natural"]["2d"]["primary"]
        crit["4 natural dev"] = {"value": nn, "main system": nm, "gap": nn - nm, "pass": nn >= nm - 0.03}
        res["criteria"][n] = crit
    json.dump(res, open("results/main_v04/reliability_step2v2_dev.json", "w"), indent=1, default=float)
    print("thresholds:", json.dumps(th))
    print("clarity probe:", json.dumps({k: v for k, v in res["clarity_probe"].items() if k != "grid"}))
    for n, crit in res["criteria"].items():
        for k, v in crit.items():
            print(f"{n} CRITERION {k}: {'PASS' if v['pass'] else 'FAIL'}")
            for ck, cv in (v.get("cells") or {"": {a: b for a, b in v.items() if a != 'pass'}}).items():
                print("   ", ck, json.dumps({a: (round(b, 3) if isinstance(b, float) else b) for a, b in cv.items()}))
    for part, cs in C_.items():
        for cond, ns in cs.items():
            print(f"== {part} / {cond}: accuracy | group all-right | mean confidence | confident share | "
                  f"confident errors")
            for n, lvs in ns.items():
                cells = []
                for lv, x in lvs.items():
                    ce = "n/a" if x["confident_error_rate"] is None else f"{x['confident_error_rate']:.3f}"
                    cells.append(f"{lv[1:]}: {x['accuracy']:.3f} {G_[part][cond][n][lv]:.3f} {x['mean_conf']:.3f} "
                                 f"{x['confident_share']:.3f} {ce}")
                print(f"  {n:9s} " + " | ".join(cells))
    print("-> results/main_v04/reliability_step2v2_dev.json")


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if cmd == "probe":
        probe()
    elif cmd == "fit":
        fit()
    elif cmd == "eval":
        eval_()
    else:
        raise SystemExit(__doc__)
